function put(data) {
    const { java, source, cookie } = this;
    return source.setVariable(JSON.stringify(data, null, '\t'));
}

function Get(e) {
    const { java, source, cookie } = this;
    var get = JSON.parse(source.getVariable());
    return get[e];
}

function n(e) {
    let line = '\n';
    const count = parseInt(e, 10) || 1;
    for (let m = 1; m < count; m++) {
        line += '\n';
    }
    return line;
}

